// Um item por PDF (para extrair o texto) + um item com os dados da página, textos e imagens
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const textos = []; const imagens = {}; const ignorados = [];
  for (const [k, b] of Object.entries(it.binary || {})) {
    if (!k.startsWith('Transcrição')) continue; // ignora outros campos de arquivo (ex.: a Proposta gerada)
    const mt = b.mimeType || ''; const nome = b.fileName || k;
    if (mt === 'application/pdf') out.push({ json: { page_id: it.json.id, tipo: 'pdf', nome }, binary: { data: b }, pairedItem: { item: i } });
    else if (mt.startsWith('image/')) imagens[k] = b;
    else if (mt.startsWith('text/') || /\.(txt|md|vtt|srt|csv)$/i.test(nome)) {
      const buf = await this.helpers.getBinaryDataBuffer(i, k);
      textos.push('--- Arquivo ' + nome + ' ---\n' + buf.toString('utf8'));
    } else ignorados.push(nome + ' (' + (mt || 'tipo desconhecido') + ')');
  }
  out.push({ json: { page_id: it.json.id, tipo: 'meta', props: it.json.properties || {}, textos, imagens, ignorados }, pairedItem: { item: i } });
}
return out;

// Junta tudo por página. PDF com texto normal vai como texto (barato);
// PDF com pouco texto por página (escaneado, prints) continua indo como PDF completo.
const FASE = 'triagem';
const sep = $('Separar arquivos (novo)').all();
const ext = $input.all();
const paginas = new Map();
for (let i = 0; i < sep.length; i++) {
  const s = sep[i]; const pid = s.json.page_id;
  if (!paginas.has(pid)) paginas.set(pid, { idx: i, meta: null, pdfTextos: [], anexos: {} });
  const pg = paginas.get(pid);
  if (s.json.tipo === 'meta') { pg.meta = s.json; continue; }
  const e = ext[i]?.json || {};
  const texto = String(e.text || '').replace(/\n{3,}/g, '\n\n').trim();
  const nPag = Number(e.numpages) || 1;
  if (texto && texto.length / nPag >= 300) pg.pdfTextos.push('--- Transcrição em PDF: ' + s.json.nome + ' (' + nPag + ' páginas) ---\n' + texto);
  else pg.anexos['pdf_' + Object.keys(pg.anexos).length] = s.binary.data;
}
const out = [];
for (const [pid, pg] of paginas) {
  const m = pg.meta || { props: {}, textos: [], imagens: {}, ignorados: [] };
  const p = m.props;
  const lead = (p['Lead']?.title || []).map(t => t.plain_text).join('') || 'Lead';
  const people = p['Gerente de contas']?.people || [];
  const resp = (p['Respostas do cliente']?.rich_text || []).map(t => t.plain_text).join('');
  let diag = [...pg.pdfTextos, ...m.textos].join('\n\n');
  if (diag.length > 400000) diag = diag.slice(0, 400000) + '\n[...cortado por tamanho]';
  if (m.ignorados.length) diag += '\n\n[Aviso: não foi possível ler estes arquivos; registre em alertas: ' + m.ignorados.join(', ') + ']';
  if (FASE === 'triagem') { if (resp) diag += '\n\nRespostas do cliente às perguntas enviadas:\n' + resp; }
  else diag += resp ? '\n\nRespostas do cliente às perguntas enviadas (valem mais que a transcrição):\n' + resp : '\n\nO cliente ainda não respondeu as perguntas; precifique com premissas conservadoras declaradas.';
  out.push({ json: { fase: FASE, page_id: pid, Lead: lead, 'Gerente de contas': people[0]?.name || '', gerente_id: people[0]?.id || '', custo_anterior: p['Custo do agente (US$)']?.number || 0, 'Diagnóstico': diag.trim(), arquivos_como_texto: pg.pdfTextos.length, arquivos_como_pdf: Object.keys(pg.anexos).length }, binary: { ...pg.anexos, ...m.imagens }, pairedItem: { item: pg.idx } });
}
return out;

const s = $('Ler arquivos (novo)').item;
const j = { ...s.json };
// 2ª rodada: o gerente colou respostas e escolheu o Status "Mais perguntas"
const pg = $('Buscar novos').all().find(x => x.json.id === j.page_id);
const status = pg?.json?.properties?.Status?.select?.name;
j.rodada = (status === 'Mais perguntas' && String(j['Diagnóstico'] || '').includes('Respostas do cliente às perguntas enviadas')) ? 2 : 1;
if (j.rodada === 2) j['Diagnóstico'] += '\n\nSEGUNDA RODADA DE PERGUNTAS. O cliente já respondeu a primeira rodada (acima). Em perguntas_cliente inclua SOMENTE: (a) dúvidas novas que surgiram a partir das respostas e (b) itens com prioridade que ficaram sem resposta. No máximo 4, só o que muda preço, prazo ou formato do Discovery. Não peça de novo nada que o cliente já respondeu ou já prometeu enviar. Se o cliente disse que outra pessoa sabe a resposta (ex.: "isso é com o fulano"), pergunte se ele pode encaminhar a pergunta para essa pessoa ou passar o contato, em vez de repetir a pergunta para ele.';
return { json: j, binary: s.binary || {} };

// Dados do lead (vindos do Notion), pela fase que gerou este item
const meta = (() => {
  for (const n of ['Preparar triagem', 'Preparar precificação']) {
    try { return $(n).item.json; } catch (e) {}
  }
  return {};
})();
const texto = $input.item.json.content[0].text;
let t;
try {
  t = JSON.parse(texto.slice(texto.indexOf('{'), texto.lastIndexOf('}') + 1));
} catch (e) {
  throw new Error('A triagem não voltou em JSON válido. Fim da resposta: ' + texto.slice(-300));
}
if (!t.criterios) throw new Error('A triagem não trouxe os critérios de dimensionamento.');

// Parâmetros da skill (seção 0)
const VALOR_DIA = 152.98;
const VALOR_DIA_HIST = 87.72;
const PESOS = { gerente: 1.00, especialista: 0.75, analista_produto: 0.55, analista_dados_dev: 0.55 };
const ancora = Math.round(2.85 * 20 * VALOR_DIA_HIST);
if (Math.abs(ancora - 5000) > 5) throw new Error('Âncora não fecha: ' + ancora);

// Regra de dimensionamento (seção 4): a IA responde critérios, o código decide
const c = t.criterios;
const frentes = Number(c.frentes) || 1;
const usuarios = Number(c.usuarios_chave) || 99;
const time = c.dados_centrais === true
  ? { gerente: 1, especialista: 1, analista_produto: 1, analista_dados_dev: 1 }
  : { gerente: 1, especialista: 1, analista_produto: 2, analista_dados_dev: 0 };
const unidades = Object.keys(PESOS).reduce((s, k) => s + time[k] * PESOS[k], 0);
const precoDe = sem => Math.round((unidades * sem * 5 * VALOR_DIA) / 100) * 100;

// A exceção de 4 semanas só vale com FATOS confirmados pelo cliente:
// número de usuários dito por ele e fluxo atual descrito por ele por escrito.
// Opinião do agente não reduz preço; vale a regra conservadora e a confirmação vira pergunta.
let aviso_criterio = '';
let semanas, regra; const confirmar = [];
if (frentes >= 3) { semanas = 6; regra = '3+ frentes interconectadas → 6 semanas'; }
else if (frentes === 1 && usuarios <= 3) {
  const sim = v => v === true || String(v).toLowerCase() === 'true';
  if (!sim(c.usuarios_chave_confirmado)) confirmar.push('usuarios');
  if (!sim(c.fluxo_confirmado)) confirmar.push('fluxo');
  if (!('fluxo_confirmado' in c)) aviso_criterio = 'A IA não devolveu o critério fluxo_confirmado: confira a justificativa antes de aprovar.';
  if (!confirmar.length) { semanas = 4; regra = '1 frente, até 3 usuários e fluxo atual confirmados pelo cliente → exceção de 4 semanas'; }
  else { semanas = 5; regra = 'padrão → 5 semanas (a exceção de 4 semanas exige confirmação do cliente: ' + confirmar.map(x => x === 'usuarios' ? 'número de usuários' : 'fluxo atual por escrito').join(' e ') + ')'; }
}
else { semanas = 5; regra = 'padrão → 5 semanas'; }
if (c.colegiado_no_processo === true && semanas < 6) { semanas += 1; regra += '; decisão colegiada durante o Discovery → +1 semana'; }
const dias = semanas * 5;
const preco_alvo = precoDe(semanas);
const alertas = (t.alertas || []).slice();
if (aviso_criterio) alertas.unshift(aviso_criterio);
if (c.escopo_amplo_demais === true) alertas.unshift('Escopo amplo demais para 6 semanas: confira o recorte da frente âncora nas premissas.');

// Fora do padrão: o preço continua o de tabela; quem decide ajuste (prêmio ou desconto) é um humano
const motivos = [];
if (t.criticidade === 'alta') motivos.push('criticidade alta');
if (c.escopo_amplo_demais === true) motivos.push('escopo amplo demais');
if (c.trabalho_campo_distante === true) motivos.push('trabalho de campo distante');
if (c.sensibilidade_preco === true) motivos.push('sensibilidade a preço ou desconto prometido');
const fora_do_padrao = motivos.length > 0;
const aviso_ajuste = fora_do_padrao
  ? '⚠️ Preço de tabela. Caso fora do padrão (' + motivos.join(', ') + '): decida se cabe adicional de risco ou deslocamento, ou se o desconto prometido se mantém, antes de aprovar.'
  : 'Caso padrão: preço de tabela sem ajuste.';

const emoji = { verde: '🟢', amarelo: '🟡', vermelho: '🔴', baixa: '🟢', media: '🟡', alta: '🔴' };
const min = s => s ? s.charAt(0).toLowerCase() + s.slice(1) : '';
const pc = (t.perguntas_cliente || []).sort((a, b) => (b.prioridade === true) - (a.prioridade === true));
if (confirmar.includes('fluxo')) pc.unshift({ pergunta: 'Você consegue descrever em poucas linhas, passo a passo, como esse processo funciona hoje (quem faz cada etapa e em qual ferramenta)?', para_que: 'Definir o tamanho do Discovery', prioridade: true });
if (confirmar.includes('usuarios')) pc.unshift({ pergunta: 'Quantas pessoas da equipe de vocês participam desse processo hoje e poderiam ser entrevistadas?', para_que: 'Definir o tamanho do Discovery', prioridade: true });
const pendencias = pc.map((p, i) => `${i + 1}. ${p.pergunta}${p.para_que ? ' (para ' + min(p.para_que) + ')' : ''}`).join('\n');
const listaG = (t.gargalos || []).map(g => `- [${g.status}] ${g.item}: ${g.desbloqueia}${g.trecho ? ' (' + g.trecho + ')' : ''}`);
if (confirmar.length) {
  const oque = confirmar.map(x => x === 'usuarios' ? `o número de pessoas a entrevistar (o agente estimou ${usuarios})` : 'o passo a passo do processo atual, por escrito').join(' e ');
  listaG.unshift(`- [bloqueia_preco] Falta o cliente confirmar ${oque}. Com isso confirmado, o Discovery cai para 4 semanas (R$ ${precoDe(4)}); por enquanto vale o preço conservador.`);
}
const gargalos = listaG.join('\n');

return { json: {
  fase: meta.fase, page_id: meta.page_id, gerente_id: meta.gerente_id,
  lead: meta.Lead, gerente: meta['Gerente de contas'],
  veredito: t.veredito, veredito_emoji: emoji[t.veredito] || '', motivo_veredito: t.motivo_veredito,
  criticidade: t.criticidade, criticidade_emoji: emoji[t.criticidade] || '', motivo_criticidade: t.motivo_criticidade,
  resumo: t.resumo, criterios: c, regra_aplicada: regra,
  fora_do_padrao, aviso_ajuste,
  semanas, dias, time, unidades: Number(unidades.toFixed(2)), preco_alvo,
  justificativa_dimensionamento: `Regra aplicada: ${regra}.\n${t.justificativa_dimensionamento || ''}`,
  pendencias, gargalos,
  perguntas_gerente: (t.perguntas_gerente || []).map((q, i) => `${i + 1}. ${q}`).join('\n'),
  premissas: (t.premissas || []).join('\n'),
  alertas: alertas.join('\n')
} };

const d = $('Calcular preço').item.json;
const LIDER = '<ID_NOTION>';
const hoje = $now.setZone('America/Recife').toFormat('dd/MM HH:mm');
const rt = s => { s = String(s || ''); const out = []; for (let i = 0; i < s.length; i += 1900) out.push({ type: 'text', text: { content: s.slice(i, i + 1900) } }); return out.length ? out : [{ type: 'text', text: { content: ' ' } }]; };
const para = s => ({ object: 'block', type: 'paragraph', paragraph: { rich_text: rt(s) } });
const h2 = s => ({ object: 'block', type: 'heading_2', heading_2: { rich_text: rt(s) } });
const h3 = s => ({ object: 'block', type: 'heading_3', heading_3: { rich_text: rt(s) } });
const bullet = s => ({ object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: rt(s) } });
const quote = s => ({ object: 'block', type: 'quote', quote: { rich_text: rt(s) } });
const cinza = s => ({ object: 'block', type: 'paragraph', paragraph: { rich_text: [{ type: 'text', text: { content: s }, annotations: { italic: true, color: 'gray' } }] } });
const lines = s => String(s || '').split('\n').map(x => x.trim()).filter(Boolean);
const mention = (id, txt) => ({ object: 'block', type: 'paragraph', paragraph: { rich_text: [ ...(id ? [{ type: 'mention', mention: { type: 'user', user: { id } } }] : []), { type: 'text', text: { content: txt } } ] } });
const reais = n => 'R$ ' + String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const semaforo = { verde: 'Verde', amarelo: 'Amarelo', vermelho: 'Vermelho' }[d.veredito];
const crit = { baixa: 'Baixa', media: 'Média', alta: 'Alta' }[d.criticidade];

// Custo desta rodada (preços do Sonnet 4.6 em US$ por milhão de tokens)
const custoDe = u => u ? ((u.input_tokens || 0) * 3 + (u.cache_creation_input_tokens || 0) * 3.75 + (u.cache_read_input_tokens || 0) * 0.3 + (u.output_tokens || 0) * 15) / 1e6 : 0;
const tokensDe = u => u ? (u.input_tokens || 0) + (u.cache_creation_input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.output_tokens || 0) : 0;
const usos = [];
try { usos.push($('Triagem').item.json.usage); } catch (e) {}
try { usos.push($('Revisar coerência').item.json.usage); } catch (e) {}
if (d.fase === 'triagem') usos.push($input.item.json.usage);
const custo = usos.reduce((s, u) => s + custoDe(u), 0);
const tokens = usos.reduce((s, u) => s + tokensDe(u), 0);
const meta = (() => { for (const n of ['Preparar triagem', 'Preparar precificação']) { try { return $(n).item.json; } catch (e) {} } return {}; })();
const total = (Number(meta.custo_anterior) || 0) + custo;
const linhaCusto = cinza(`Custo desta rodada: US$ ${custo.toFixed(3)} (${Math.round(tokens / 1000)} mil tokens, ${usos.filter(Boolean).length} chamada(s)). Total do lead até aqui: US$ ${total.toFixed(2)}.`);

let children = [];
const properties = {};
if (semaforo) properties['Semáforo'] = { select: { name: semaforo } };
if (crit) properties['Criticidade'] = { select: { name: crit } };
properties['Custo do agente (US$)'] = { number: Math.round(total * 1000) / 1000 };

if (d.fase === 'triagem') {
  const msg = $input.item.json.content?.[0]?.text || '';
  const nPerg = (msg.match(/^\s*\*?\d+[.)]/gm) || []).length;
  children = [
    meta.rodada === 2
      ? h2(`🔎 2ª rodada de perguntas · ${hoje} · ${d.veredito_emoji} ${semaforo || d.veredito} · ${nPerg} perguntas para o cliente`)
      : h2(`🔎 Triagem · ${hoje} · ${d.veredito_emoji} ${semaforo || d.veredito} · ${nPerg} perguntas para o cliente`),
    meta.rodada === 2
      ? mention(d.gerente_id, ' a 2ª rodada está pronta: só o que as respostas deixaram em aberto. Envie ao cliente, cole as novas respostas abaixo das anteriores no campo "Respostas do cliente" e mude o Status para "Pronto para precificar".')
      : mention(d.gerente_id, ' a triagem está pronta. Revise a mensagem abaixo, envie ao cliente pelo WhatsApp e cole as respostas no campo "Respostas do cliente". Depois mude o Status para "Pronto para precificar" ou, se as respostas abrirem novas dúvidas, para "Mais perguntas".'),
    para(`Semáforo: ${d.veredito_emoji} ${d.veredito} — ${d.motivo_veredito}`),
    para(`Criticidade: ${d.criticidade_emoji} ${d.criticidade} — ${d.motivo_criticidade}`),
    h3('Riscos encontrados'),
    ...lines(d.gargalos).slice(0, 12).map(l => bullet(l.replace(/^- /, ''))),
    h3('Mensagem para o cliente (revise antes de enviar)'),
    quote(msg),
    h3('Para o gerente de contas confirmar'),
    ...lines(d.perguntas_gerente).map(l => bullet(l.replace(/^\d+\.\s*/, ''))),
    h3('Alertas'),
    ...lines(d.alertas).map(bullet),
    linhaCusto
  ];
  properties['Status'] = { select: { name: 'Perguntas prontas' } };
} else {
  const t = d.time || {};
  const analistas = (t.analista_produto || 0) + (t.analista_dados_dev || 0);
  const timeTxt = `${t.gerente || 0} gerente, ${t.especialista || 0} especialista, ${analistas} analista(s)${t.analista_dados_dev ? ' (1 de dados/dev)' : ''}`;
  const bloqueios = lines(d.gargalos).filter(l => l.includes('[bloqueia_preco]'));
  children = [
    h2(`💰 Precificação · ${hoje} · ${reais(d.preco_alvo)} · ${d.semanas} semanas${d.fora_do_padrao ? ' · ⚠️ fora do padrão' : ''}`),
    mention(LIDER, ' a precificação está pronta para sua aprovação. Mude o Status para "Aprovado" ou "Ajustar" (e comente o ajuste).'),
    ...(d.fora_do_padrao ? [para(d.aviso_ajuste)] : []),
    para(`Preço de tabela: ${reais(d.preco_alvo)} · ${d.semanas} semanas · ${timeTxt}`),
    para(d.justificativa_dimensionamento),
    para(`Semáforo: ${d.veredito_emoji} ${d.veredito} — ${d.motivo_veredito}`),
    h3('Ainda bloqueia o preço'),
    ...(bloqueios.length ? bloqueios.map(l => bullet(l.replace(/^- \[bloqueia_preco\] /, ''))) : [para('Nada. As respostas do cliente cobriram o que faltava.')]),
    h3('Alertas'),
    ...lines(d.alertas).map(bullet),
    linhaCusto
  ];
  properties['Status'] = { select: { name: 'Aguardando aprovação' } };
  properties['Preço de tabela'] = { number: d.preco_alvo };
  properties['Semanas'] = { number: d.semanas };
  properties['Fora do padrão'] = { checkbox: !!d.fora_do_padrao };
}
return { json: { page_id: d.page_id, children: children.slice(0, 95), properties } };

const meta = (() => {
  for (const n of ['Preparar triagem', 'Preparar precificação', 'Preparar proposta']) {
    try { const j = $(n).item.json; if (j && j.page_id) return j; } catch (e) {}
  }
  return {};
})();
if (!meta.page_id) throw new Error('Erro sem página associada: ' + JSON.stringify($json).slice(0, 300));
const LIDER = '<ID_NOTION>';
const e = $json.error;
const msg = String((e && (e.description || e.message)) || e || 'erro desconhecido').slice(0, 1500);
const semCredito = /credit balance is too low/i.test(msg);
const hoje = $now.setZone('America/Recife').toFormat('dd/MM HH:mm');
const etapa = { triagem: 'triagem', precificacao: 'precificação', proposta: 'geração da proposta' }[meta.fase] || 'análise';
const voltar = { triagem: 'Novo', precificacao: 'Pronto para precificar', proposta: 'Gerando proposta' }[meta.fase] || 'Novo';
const rich = [{ type: 'mention', mention: { type: 'user', user: { id: LIDER } } }];
if (meta.gerente_id && meta.gerente_id !== LIDER) rich.push({ type: 'text', text: { content: ' ' } }, { type: 'mention', mention: { type: 'user', user: { id: meta.gerente_id } } });
const dica = semCredito ? 'Acabaram os créditos da API da Anthropic. Recarregue em console.anthropic.com (Billing)' : 'Confira os arquivos (PDF ou .txt funcionam melhor)';
rich.push({ type: 'text', text: { content: ` o agente não conseguiu terminar a ${etapa} desta página. ${dica} e mude o Status para "${voltar}" para tentar de novo.` } });
return { json: {
  page_id: meta.page_id,
  properties: { Status: { select: { name: 'Erro no agente' } } },
  children: [
    { object: 'block', type: 'heading_2', heading_2: { rich_text: [{ type: 'text', text: { content: '⚠️ Erro do agente · ' + hoje } }] } },
    { object: 'block', type: 'paragraph', paragraph: { rich_text: rich } },
    { object: 'block', type: 'paragraph', paragraph: { rich_text: [{ type: 'text', text: { content: 'Detalhe técnico: ' + msg } }] } }
  ]
} };

// Seções antigas do agente viram títulos toggle; a nova seção fica aberta
const novo = (() => {
  for (const n of ['Montar página', 'Montar erro', 'Montar decisão', 'Montar entrega']) {
    try { return $(n).item.json; } catch (e) {}
  }
  return null;
})();
if (!novo) throw new Error('Não achei a nova seção a escrever.');
const pagina = $('Atualizar propriedades').item.json;
const BOT = pagina.last_edited_by?.id;
const blocks = $json.results || [];
const txt = b => (b[b.type]?.rich_text || []).map(r => r.plain_text).join('');
const MARCA = /^(🔎|💰|⚠️|✅|✏️|📄)/;
const ehMarca = b => b.type === 'heading_2' && !b.heading_2.is_toggleable && b.created_by?.id === BOT && MARCA.test(txt(b));

const secoes = []; let atual = null;
for (const b of blocks) {
  if (ehMarca(b)) { atual = { head: b, body: [] }; secoes.push(atual); continue; }
  if (!atual) continue;
  if (b.type === 'heading_2' || b.created_by?.id !== BOT) { atual = null; continue; }
  atual.body.push(b);
}

const pedacos = (s, r) => { s = String(s || ''); const out = []; for (let i = 0; i < s.length; i += 1900) out.push({ type: 'text', text: { content: s.slice(i, i + 1900), link: r.text?.link || null }, annotations: r.annotations }); return out.length ? out : [{ type: 'text', text: { content: ' ' }, annotations: r.annotations }]; };
const limpa = rich => (rich || []).flatMap(r => {
  if (r.type === 'mention' && r.mention?.type === 'user') return [{ type: 'mention', mention: { type: 'user', user: { id: r.mention.user.id } }, annotations: r.annotations }];
  if (r.type === 'text') return pedacos(r.text.content, r);
  return pedacos(r.plain_text || '', r);
});
const TIPOS = ['paragraph', 'bulleted_list_item', 'numbered_list_item', 'quote', 'heading_3', 'callout'];
const copia = b => ({ object: 'block', type: b.type, [b.type]: { rich_text: limpa(b[b.type].rich_text) } });
const toggles = secoes.map(s => ({
  object: 'block', type: 'heading_2',
  heading_2: { rich_text: limpa(s.head.heading_2.rich_text), is_toggleable: true, children: s.body.filter(b => TIPOS.includes(b.type)).slice(0, 100).map(copia) }
}));
return { json: {
  page_id: pagina.id,
  children: [...toggles, ...novo.children].slice(0, 100),
  delete_ids: secoes.flatMap(s => [s.head.id, ...s.body.map(b => b.id)])
} };

// Um item por PDF (para extrair o texto) + um item com os dados da página, textos e imagens
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const textos = []; const imagens = {}; const ignorados = [];
  for (const [k, b] of Object.entries(it.binary || {})) {
    if (!k.startsWith('Transcrição')) continue; // ignora outros campos de arquivo (ex.: a Proposta gerada)
    const mt = b.mimeType || ''; const nome = b.fileName || k;
    if (mt === 'application/pdf') out.push({ json: { page_id: it.json.id, tipo: 'pdf', nome }, binary: { data: b }, pairedItem: { item: i } });
    else if (mt.startsWith('image/')) imagens[k] = b;
    else if (mt.startsWith('text/') || /\.(txt|md|vtt|srt|csv)$/i.test(nome)) {
      const buf = await this.helpers.getBinaryDataBuffer(i, k);
      textos.push('--- Arquivo ' + nome + ' ---\n' + buf.toString('utf8'));
    } else ignorados.push(nome + ' (' + (mt || 'tipo desconhecido') + ')');
  }
  out.push({ json: { page_id: it.json.id, tipo: 'meta', props: it.json.properties || {}, textos, imagens, ignorados }, pairedItem: { item: i } });
}
return out;

// Junta tudo por página. PDF com texto normal vai como texto (barato);
// PDF com pouco texto por página (escaneado, prints) continua indo como PDF completo.
const FASE = 'precificacao';
const sep = $('Separar arquivos (preço)').all();
const ext = $input.all();
const paginas = new Map();
for (let i = 0; i < sep.length; i++) {
  const s = sep[i]; const pid = s.json.page_id;
  if (!paginas.has(pid)) paginas.set(pid, { idx: i, meta: null, pdfTextos: [], anexos: {} });
  const pg = paginas.get(pid);
  if (s.json.tipo === 'meta') { pg.meta = s.json; continue; }
  const e = ext[i]?.json || {};
  const texto = String(e.text || '').replace(/\n{3,}/g, '\n\n').trim();
  const nPag = Number(e.numpages) || 1;
  if (texto && texto.length / nPag >= 300) pg.pdfTextos.push('--- Transcrição em PDF: ' + s.json.nome + ' (' + nPag + ' páginas) ---\n' + texto);
  else pg.anexos['pdf_' + Object.keys(pg.anexos).length] = s.binary.data;
}
const out = [];
for (const [pid, pg] of paginas) {
  const m = pg.meta || { props: {}, textos: [], imagens: {}, ignorados: [] };
  const p = m.props;
  const lead = (p['Lead']?.title || []).map(t => t.plain_text).join('') || 'Lead';
  const people = p['Gerente de contas']?.people || [];
  const resp = (p['Respostas do cliente']?.rich_text || []).map(t => t.plain_text).join('');
  let diag = [...pg.pdfTextos, ...m.textos].join('\n\n');
  if (diag.length > 400000) diag = diag.slice(0, 400000) + '\n[...cortado por tamanho]';
  if (m.ignorados.length) diag += '\n\n[Aviso: não foi possível ler estes arquivos; registre em alertas: ' + m.ignorados.join(', ') + ']';
  if (FASE === 'triagem') { if (resp) diag += '\n\nRespostas do cliente às perguntas enviadas:\n' + resp; }
  else diag += resp ? '\n\nRespostas do cliente às perguntas enviadas (valem mais que a transcrição):\n' + resp : '\n\nO cliente ainda não respondeu as perguntas; precifique com premissas conservadoras declaradas.';
  out.push({ json: { fase: FASE, page_id: pid, Lead: lead, 'Gerente de contas': people[0]?.name || '', gerente_id: people[0]?.id || '', custo_anterior: p['Custo do agente (US$)']?.number || 0, 'Diagnóstico': diag.trim(), arquivos_como_texto: pg.pdfTextos.length, arquivos_como_pdf: Object.keys(pg.anexos).length }, binary: { ...pg.anexos, ...m.imagens }, pairedItem: { item: pg.idx } });
}
return out;

const p = $json.properties || {};
const status = p['Status']?.select?.name;
const tabela = p['Preço de tabela']?.number;
const final = p['Preço final']?.number;
const semanas = p['Semanas']?.number;
const motivo = (p['Motivo do ajuste']?.rich_text || []).map(t => t.plain_text).join('');
const gerente = p['Gerente de contas']?.people?.[0]?.id || '';
const decisor = $json.last_edited_by?.id || '';
const hoje = $now.setZone('America/Recife').toFormat('dd/MM HH:mm');
const reais = n => 'R$ ' + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const rt = s => [{ type: 'text', text: { content: String(s).slice(0, 1900) } }];
const men = id => ({ type: 'mention', mention: { type: 'user', user: { id } } });
const para = rich => ({ object: 'block', type: 'paragraph', paragraph: { rich_text: rich } });
const h2 = s => ({ object: 'block', type: 'heading_2', heading_2: { rich_text: rt(s) } });
const sem = semanas ? ` · ${semanas} semanas` : '';
const aviso = ' O rascunho da proposta (Word e PDF) está sendo gerado e aparece aqui em alguns minutos.';

const preco = status === 'Aprovado' ? (final ?? tabela) : final;
if (preco == null) {
  return { json: { page_id: $json.id,
    properties: { Status: { select: { name: 'Aguardando aprovação' } } },
    children: [h2('⚠️ Erro do agente · ' + hoje), para([...(decisor ? [men(decisor)] : []), ...rt(' não há preço para aprovar nesta página. Preencha "Preço final" ou rode a precificação antes de aprovar.')])] } };
}

const quem = [...(gerente ? [men(gerente)] : [])];
let children;
if (status === 'Aprovado' && (final == null || final === tabela)) {
  children = [
    h2(`✅ Preço aprovado · ${hoje} · ${reais(preco)}${sem}`),
    para([...quem, ...rt(' o preço de tabela foi aprovado' + (decisor ? ' por ' : '.')), ...(decisor ? [men(decisor)] : []), ...rt(`${decisor ? '.' : ''} Valor final: ${reais(preco)}${sem}.` + aviso)])
  ];
} else {
  const dif = tabela ? preco - tabela : null;
  const pct = tabela ? Math.round((dif / tabela) * 100) : null;
  const difTxt = dif == null ? '' : `Diferença para o preço de tabela (${reais(tabela)}): ${dif >= 0 ? '+' : '−'}${reais(Math.abs(dif))} (${pct >= 0 ? '+' : ''}${pct}%).`;
  children = [
    h2(`✏️ Preço ajustado · ${hoje} · ${reais(preco)}${tabela ? ' (tabela ' + reais(tabela) + ')' : ''}`),
    para([...quem, ...rt(' o preço foi ajustado' + (decisor ? ' por ' : '.')), ...(decisor ? [men(decisor)] : []), ...rt(`${decisor ? '.' : ''} Valor final: ${reais(preco)}${sem}.` + aviso)]),
    ...(difTxt ? [para(rt(difTxt))] : []),
    para(rt('Motivo do ajuste: ' + (motivo || 'não informado.')))
  ];
}
return { json: { page_id: $json.id,
  properties: { Status: { select: { name: 'Gerando proposta' } }, 'Preço final': { number: preco } },
  children } };

// Um item por PDF (para extrair o texto); arquivos de texto já são lidos aqui
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const textos = []; const ignorados = [];
  let pdfs = 0;
  for (const [k, b] of Object.entries(it.binary || {})) {
    if (!k.startsWith('Transcrição')) continue; // ignora outros campos de arquivo (ex.: a Proposta gerada)
    const mt = b.mimeType || ''; const nome = b.fileName || k;
    if (mt === 'application/pdf') { pdfs++; out.push({ json: { nome }, binary: { data: b }, pairedItem: { item: i } }); }
    else if (mt.startsWith('text/') || /\.(txt|md|vtt|srt|csv)$/i.test(nome)) {
      const buf = await this.helpers.getBinaryDataBuffer(i, k);
      textos.push('--- Arquivo ' + nome + ' ---\n' + buf.toString('utf8'));
    } else ignorados.push(nome);
  }
  out.push({ json: { nome: '__textos__', textos, ignorados }, pairedItem: { item: i } });
}
return out;

// Monta o pedido para o Claude gerar a proposta com a skill (o texto dos PDFs vai direto no pedido)
const SKILL_ID = 'skill_<SEU_ID>';
const out = [];
const page = $('Buscar para proposta').first();
const items = [page];
const extraidos = $input.all().map(x => x.json);
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const p = it.json.properties || {};
  const lead = (p['Lead']?.title || []).map(t => t.plain_text).join('') || 'Lead';
  const people = p['Gerente de contas']?.people || [];
  const resp = (p['Respostas do cliente']?.rich_text || []).map(t => t.plain_text).join('');
  const motivo = (p['Motivo do ajuste']?.rich_text || []).map(t => t.plain_text).join('');
  const tabela = p['Preço de tabela']?.number;
  const final = p['Preço final']?.number;
  const preco = final ?? tabela;
  const semanas = p['Semanas']?.number || 5;
  const docs = [];
  const meta = $('Separar arquivos (proposta)').all().map(x => x.json).find(j => j.nome === '__textos__') || { textos: [], ignorados: [] };
  const textos = [...meta.textos];
  const ignorados = [...meta.ignorados];
  for (const j of extraidos) {
    if (j.nome === '__textos__') continue;
    if (j.text) textos.push('--- Transcrição em PDF (' + (j.numpages || '?') + ' páginas) ---\n' + String(j.text).replace(/\n{3,}/g, '\n\n'));
  }
  let total = 0;
  for (let t = 0; t < textos.length; t++) { if (total + textos[t].length > 400000) { textos[t] = textos[t].slice(0, Math.max(0, 400000 - total)) + '\n[...cortado por tamanho]'; } total += textos[t].length; }
  const reais = n => 'R$ ' + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const nomeArq = lead.replace(/\(.*?\)/g, '').trim().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '') || 'Lead';
  const prompt = [
    'Você está rodando de forma automática dentro do Notion da CITi, sem ninguém para responder perguntas.',
    'Use a skill proposta-discovery-enterprise para gerar a proposta de Discovery Enterprise deste lead. Leia SOMENTE /skills/proposta-discovery-enterprise/SKILL.md (não leia /skills/docx/SKILL.md: as regras de docx-js necessárias estão abaixo).',
    '',
    'DADOS FECHADOS (já aprovados pela liderança; não recalcule nem questione):',
    `- Lead: ${lead.replace(/\s*\(teste\)/i, '')}`,
    `- Investimento: ${reais(preco)}`,
    `- Prazo: ${semanas} semanas (${semanas * 5} dias úteis), com ${semanas} sprints conforme a seção 3 da skill`,
    `- Parcelamento: até 2× de ${reais(preco / 2)}`,
    ...(motivo ? [`- Contexto interno do preço (NÃO cite no documento): ${motivo}`] : []),
    '',
    'FONTES: abaixo está o texto da(s) transcrição(ões) e/ou do diagnóstico comercial da reunião.',
    ...(textos.length ? textos : ['(nenhuma transcrição legível foi encontrada)']),
    ...(resp ? ['', 'Respostas do cliente às perguntas enviadas depois da reunião (valem mais que a transcrição):', resp] : []),
    ...(ignorados.length ? ['', 'Arquivos que não puderam ser lidos: ' + ignorados.join(', ')] : []),
    '',
    'REGRAS DE EXECUÇÃO (cada passo extra custa caro, então trabalhe em poucos comandos):',
    '- Não faça perguntas. Se faltar razão social ou decisor, siga a regra da skill (nome curto, sem citar decisor).',
    '- Passo 1: leia a skill. Passo 2: escreva o script Node completo de uma vez (require(\'docx\') já está instalado) e, NO MESMO comando, gere o .docx e converta para PDF com: python /skills/docx/scripts/office/soffice.py --headless --convert-to pdf <arquivo.docx>. Passo 3: verifique só com pdfinfo (número de páginas) e pdftotext | grep (preço, prazo, sprints, parcelas). Passo 4: só corrija se algo estiver errado.',
    '- NÃO renderize páginas em imagem nem abra imagens (pdftoppm proibido). Não imprima arquivos inteiros no terminal.',
    '- Regras de docx-js: tabelas precisam de columnWidths na tabela E width em cada célula, em WidthType.DXA, somando a largura da tabela; sombreamento com ShadingType.CLEAR (nunca SOLID); listas via numbering com LevelFormat.BULLET (nunca o caractere • solto); nunca use \\n dentro de texto, use parágrafos separados; PageBreak sempre dentro de um Paragraph.',
    `- No último comando, copie APENAS dois arquivos para $OUTPUT_DIR: Proposta_Discovery_${nomeArq}.docx e Proposta_Discovery_${nomeArq}.pdf, e rode ls $OUTPUT_DIR.`,
    '- Sua resposta final deve ser só uma lista curta (no máximo 6 linhas, cada uma começando com "- ") do que a liderança precisa conferir antes de enviar ao cliente.'
  ].join('\n');
  const body = {
    model: 'claude-sonnet-4-6', max_tokens: 16000,
    container: { skills: [ { type: 'custom', skill_id: SKILL_ID, version: 'latest' }, { type: 'anthropic', skill_id: 'docx', version: 'latest' } ] },
    tools: [ { type: 'code_execution_20250825', name: 'code_execution' } ],
    messages: [ { role: 'user', content: [ ...docs, { type: 'text', text: prompt, cache_control: { type: 'ephemeral' } } ] } ]
  };
  out.push({ json: { fase: 'proposta', page_id: it.json.id, Lead: lead, gerente_id: people[0]?.id || '', custo_anterior: p['Custo do agente (US$)']?.number || 0, preco, semanas, inicio: Date.now(), body }, pairedItem: { item: 0 } });
}
return out;

// A Anthropic pausou o turno (tarefa longa): reenviamos tudo o que já foi feito para ele continuar
if ($runIndex >= 12) throw new Error('A geração da proposta não terminou depois de 13 rodadas.');
const base = $('Preparar proposta').first().json.body;
const feito = [];
for (let r = 0; r <= $runIndex; r++) feito.push(...$('Escrever proposta (Claude)').all(0, r)[0].json.content);
const body = { ...base, container: { id: $json.container.id, skills: base.container.skills }, messages: [ base.messages[0], { role: 'assistant', content: feito } ] };
return [{ json: { body }, pairedItem: { item: 0 } }];

// Junta os arquivos gerados em todas as rodadas, a lista de conferência e o uso de tokens
const ids = []; let texto = ''; let entrada = 0; let saida = 0; let cache_lido = 0; let cache_criado = 0; let rodadas = 0;
for (let r = 0; r < 20; r++) {
  let res;
  try { res = $('Escrever proposta (Claude)').all(0, r); } catch (e) { break; }
  if (!res || !res.length) break;
  rodadas++;
  const j = res[0].json;
  entrada += j.usage?.input_tokens || 0; saida += j.usage?.output_tokens || 0;
  cache_lido += j.usage?.cache_read_input_tokens || 0; cache_criado += j.usage?.cache_creation_input_tokens || 0;
  const t = [];
  for (const b of j.content || []) {
    if (b.type === 'bash_code_execution_tool_result' && b.content?.type === 'bash_code_execution_result') for (const f of b.content.content || []) if (f.file_id) ids.push(f.file_id);
    if (b.type === 'text') t.push(b.text);
  }
  if (t.length) texto = t.join('\n');
}
if (!ids.length) throw new Error('A skill terminou sem gerar arquivos. Última resposta: ' + texto.slice(0, 400));
const info = { texto, entrada, saida, cache_lido, cache_criado, rodadas };
return ids.map(id => ({ json: { file_id: id, ...info }, pairedItem: { item: 0 } }));

// Fica só com o último .docx e o último .pdf gerados
const porExt = {};
const itens = $input.all();
for (let i = 0; i < itens.length; i++) {
  const m = itens[i].json;
  const ext = (m.filename || '').split('.').pop().toLowerCase();
  if (ext === 'docx' || ext === 'pdf') porExt[ext] = { file_id: m.id, filename: m.filename, mime: ext === 'pdf' ? 'application/pdf' : 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' };
}
const lista = Object.values(porExt);
if (!lista.length) throw new Error('Nenhum .docx ou .pdf entre os arquivos gerados.');
return lista.map(x => ({ json: x, pairedItem: { item: 0 } }));

// Monta a seção "Proposta pronta" e anexa os arquivos no campo Proposta
const meta = $('Preparar proposta').first().json;
const col = $('Coletar arquivos').first().json;
const ups = $('Criar upload no Notion').all().map(x => x.json);
const arqs = $('Filtrar arquivos').all().map(x => x.json);
const hoje = $now.setZone('America/Recife').toFormat('dd/MM HH:mm');
const reais = n => 'R$ ' + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const rt = s => [{ type: 'text', text: { content: String(s).slice(0, 1900) } }];
const minutos = Math.max(1, Math.round((Date.now() - meta.inicio) / 60000));
const conferir = col.texto.split('\n').map(l => l.trim()).filter(l => /^[-•*]\s+/.test(l)).map(l => l.replace(/^[-•*]\s+/, '')).slice(0, 8);
const custo = (col.entrada * 3 + (col.cache_criado || 0) * 3.75 + (col.cache_lido || 0) * 0.3 + col.saida * 15) / 1e6;
const total = (Number(meta.custo_anterior) || 0) + custo;
const files = ups.map((u, i) => ({ type: 'file_upload', file_upload: { id: u.id }, name: arqs[i]?.filename || u.filename }));
const children = [
  { object: 'block', type: 'heading_2', heading_2: { rich_text: rt(`📄 Proposta pronta · ${hoje} · ${reais(meta.preco)} · ${meta.semanas} semanas`) } },
  { object: 'block', type: 'paragraph', paragraph: { rich_text: [ ...(meta.gerente_id ? [{ type: 'mention', mention: { type: 'user', user: { id: meta.gerente_id } } }] : []), ...rt(' o rascunho da proposta está no campo "Proposta" (Word e PDF), gerado com a skill de proposta da CITi. Revise antes de enviar ao cliente.') ] } },
  ...(conferir.length ? [ { object: 'block', type: 'heading_3', heading_3: { rich_text: rt('Conferir antes de enviar') } }, ...conferir.map(c => ({ object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: rt(c) } })) ] : []),
  { object: 'block', type: 'paragraph', paragraph: { rich_text: [{ type: 'text', text: { content: `Gerado em ~${minutos} min. Custo desta rodada: US$ ${custo.toFixed(3)} (${Math.round((col.entrada + (col.cache_criado || 0) + (col.cache_lido || 0) + col.saida) / 1000)} mil tokens). Total do lead até aqui: US$ ${total.toFixed(2)}.` }, annotations: { italic: true, color: 'gray' } }] } }
];
return [{ json: { page_id: meta.page_id, properties: { Status: { select: { name: 'Proposta' } }, Proposta: { files }, 'Custo do agente (US$)': { number: Math.round(total * 1000) / 1000 } }, children }, pairedItem: { item: 0 } }];
